/bin/bash -c "node --input-type=module <<'NODE'
const base = 'http://localhost:3100'
for (const [path, options] of [
  ['/', { headers: { 'user-agent': 'migration-smoke-test' } }],
  ['/blog', {}],
  ['/blog/1', {}],
  ['/blog/11', {}],
  ['/blog/999', {}],
  ['/missing', {}],
  ['/api/posts', {}],
  ['/api/posts', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title: 'test', content: 'body' }) }],
  ['/api/posts', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title: 'test' }) }],
  ['/api/posts', { method: 'PATCH' }],
  ['/api/posts/1', {}],
  ['/api/posts/1', { method: 'PUT', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title: 'updated' }) }],
  ['/api/posts/1', { method: 'DELETE' }],
  ['/api/posts/1', { method: 'PATCH' }],
]) {
  try {
    const response = await fetch(base + path, { ...options, signal: AbortSignal.timeout(20000) })
    const content = await response.text()
    console.log(options.method ?? 'GET', path, response.status, response.headers.get('allow') ?? '', content.includes('migration-smoke-test') ? 'useragent-ok' : '', content.match(/<title>(.*?)<\\/title>/)?.[1] ?? '', content.slice(0, 170).replaceAll(/<["'^>]*>/g, '"' '))
  } catch (error) {
    console.error(options.method ?? 'GET', path, error)
  }
}
NODE
printf '\\n===== next-env.d.ts =====\\n'; cat next-env.d.ts; printf '\\n===== gitignore =====\\n'; cat .gitignore"

/bin/bash -c "node --input-type=module <<'NODE'
for(const path of ['/missing','/blog/999','/blog/11']) {
 const response=await fetch('http://localhost:3100'+path)
 const html=await response.text()
 const titles=[...html.matchAll(/<title>(.*?)<\\/title>/g)].map(match=>match[1])
 const descriptions=[...html.matchAll(/<meta name=\"description\" content=\"(.*?)\"/g)].map(match=>match[1])
 console.log(path,response.status,titles,descriptions)
}
NODE"
